      if (exact.length === 1) return { hit: exact[0], tier: 0 };
      const loose = cands.filter(c => { const cn = c.name.toLowerCase(); return cn.includes(rt) || (cn.length >= 4 && rt.includes(cn)); });
      if (loose.length === 1) return { hit: loose[0], tier: 1 };
